Tool response:
Tool: schedule_followup_appointment
Description: Schedule a 30-minute follow-up appointment.
Ensures no conflicts with existing appointments for the same provider or room.
Parameters:
    {
      "type": "object",
      "properties": {
        "patient_id": {
          "type": "integer",
          "title": "Patient Id"
        },
        "provider_id": {
          "type": "integer",
          "title": "Provider Id"
        },
        "room_id": {
          "type": "integer",
          "title": "Room Id"
        },
        "start_time": {
          "type": "string",
          "title": "Start Time"
        },
        "end_time": {
          "type": "string",
          "title": "End Time"
        },
        "notes": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "title": "Notes"
        }
      },
      "required": [
        "patient_id",
        "provider_id",
        "room_id",
        "start_time",
        "end_time"
      ]
    }

Tool response:
Tool: search_patients
Description: Find patients whose last name or first name matches the provided search term.
Parameters:
    {
      "type": "object",
      "properties": {
        "name": {
          "type": "string",
          "description": "Partial or full name of the patient to search for",
          "title": "Name"
        }
      },
      "required": [
        "name"
      ]
    }

Tool response:
Tool: search_providers
Description: Find providers whose full name or specialty matches the provided search term.
Joins with users table to get full_name.
Parameters:
    {
      "type": "object",
      "properties": {
        "term": {
          "type": "string",
          "description": "Partial or full name or specialty of the provider to search for",
          "title": "Term"
        }
      },
      "required": [
        "term"
      ]
    }
